  rule?: UnresolvedRule
): rule is RuleCharExclude =>
  rule !== undefined && rule !== null && rule instanceof RuleCharExclude;

export const isRange = (input: unknown): input is Range =>
  Array.isArray(input) &&
  input.length === 2 &&
  input.every((n) => typeof n === 'number');

