export const getParentStackId = (
  pointer: GraphPointer,
  col: (value: string | number, color: string) => string
): string => {
  const stackIds: string[] = [];
  let parent: GraphPointer | undefined = pointer.parent;
  while (parent) {
    stackIds.push(
