import { GraphNode } from './graph-node';
import { GraphPointer } from './graph-pointer';
import { Pointers } from './pointers';
import type { RuleRef } from './rule-ref';
import {
  isRange,
  isRuleChar,
  isRuleCharExclude,
  isRuleEnd,
