} from './type-guards';

export type RootNode = Map<number, GraphNode>;

export class Graph {
  private roots = new Map<number, RootNode>();
  grammar: string;
  private rootNode: RootNode;
  previousCodePoints: number[] = [];

  constructor(
    grammar: string,
