  get nodes(): Set<GraphNode> {
    if (this.nodesSet === undefined) {
      throw new Error('Nodes are not set');
    }
    return this.nodesSet;
  }

  set nodes(nodes: Set<GraphNode>) {
    this.nodesSet = nodes;
  }
}

