import { validateNonEmpty } from '../utils/validate-non-empty';

export enum InternalRuleType {
  CHAR = 'char',
  CHAR_RNG_UPPER = 'char_rng_upper',
  CHAR_ALT = 'char_alt',
  CHAR_NOT = 'char_not',
  ALT = 'alt',
  END = 'end',
  REF = 'ref',
}

